/// <summary>
///  Constructs a <c>METTransferOrderFinalisationBusinessEventContract</c>.
/// </summary>
/// <param name = "_inventTransferTable">
/// <c>InventTransferTable</c> record.
/// </param>
/// <returns>An instance of <c>METTransferOrderFinalisationBusinessEventContract</c>.</returns>
public static METTransferOrderFinalisationBusinessEventContract newFromInventTransferTable(InventTransferTable _inventTransferTable)
{
    METTransferOrderFinalisationBusinessEventContract contract = new METTransferOrderFinalisationBusinessEventContract();
    contract.initialize(_inventTransferTable);
    return contract;
}

/// <summary>
/// Initializes data variables.
/// </summary>
/// <param name = "_inventTransferTable">
/// <c>InventTransferTable</c> record.
/// </param>
private void initialize(InventTransferTable _inventTransferTable)
{
    legalEntity    = curExt();
    inventTransferId = _inventTransferTable.TransferId;
    createdBy      = _inventTransferTable.CreatedBy;
}

/// <summary>
